// Build Agent Context v2 — Long-Life Memory
const payload = $input.first().json;
const persona = payload._persona || payload.persona || {};
const userId = payload.userId;

const relevantMemories    = persona.relevant_memories     || [];
const keyFacts            = persona.key_facts             || [];
const ethicalProfile      = persona.ethical_profile       || {};
const interests           = persona.interests             || [];
const preferences         = persona.preferences           || {};
const relationshipFacts   = persona.relationship_facts    || [];
const goalsAndAspirations = persona.goals_and_aspirations || [];
const physicalStats       = persona.physical_stats        || {};

function buildUserContext(p) {
  const lines = [];
  lines.push(`👤 USER PROFILE`);
  lines.push(`Name: ${p.name || 'Unknown'}`);
  lines.push(`Language: ${p.language_preference || 'th'}`);
  lines.push(`Tier: ${p.subscriptionTier || 'FREE'}`);
  lines.push(`Timezone: ${p.timezone || 'Asia/Bangkok'}`);

  const hasStats = Object.values(physicalStats).some(v => v != null);
  if (hasStats) {
    const s = physicalStats;
    const parts = [];
    if (s.age)       parts.push(`age ${s.age}`);
    if (s.gender)    parts.push(s.gender);
    if (s.weight_kg) parts.push(`${s.weight_kg}kg`);
    if (s.height_cm) parts.push(`${s.height_cm}cm`);
    if (parts.length) lines.push(`Physical: ${parts.join(', ')}`);
  }

  if (p.personality_notes) lines.push(`Personality: ${p.personality_notes}`);

  if (keyFacts.length > 0) {
    lines.push(`\n📌 KEY FACTS (remember these always):`);
    keyFacts.slice(0, 8).forEach(f => lines.push(`  • ${f}`));
  }

  if (interests.length > 0) {
    lines.push(`\n💡 INTERESTS: ${interests.slice(0, 6).join(', ')}`);
  }

  if (Object.keys(preferences).length > 0) {
    const prefStr = Object.entries(preferences).slice(0, 4).map(([k,v]) => `${k}: ${v}`).join(', ');
    lines.push(`⚙️  PREFERENCES: ${prefStr}`);
  }

  if (relationshipFacts.length > 0) {
    lines.push(`\n❤️  RELATIONSHIPS:`);
    relationshipFacts.slice(0, 3).forEach(r => lines.push(`  • ${r}`));
  }

  if (goalsAndAspirations.length > 0) {
    lines.push(`\n🎯 GOALS & ASPIRATIONS:`);
    goalsAndAspirations.slice(0, 4).forEach(g => lines.push(`  • ${g}`));
  }

  if (ethicalProfile.growth_stage) {
    lines.push(`\n🌱 GROWTH: Stage ${ethicalProfile.growth_stage}/5 (${ethicalProfile.growth_stage_label || ''})`);
    if (ethicalProfile.top_strengths?.length) {
      lines.push(`   Strengths: ${ethicalProfile.top_strengths.join(', ')}`);
    }
  }

  if (relevantMemories.length > 0) {
    lines.push(`\n🧠 RELEVANT MEMORIES (from past conversations):`);
    relevantMemories.forEach((m, i) => {
      const sim = m.similarity ? ` [${(m.similarity*100).toFixed(0)}% match]` : '';
      lines.push(`  ${i+1}. [${m.type}]${sim} ${m.summary}`);
      if (m.insight) lines.push(`     → ${m.insight}`);
    });
  }

  return lines.join('\n');
}

const userContext = buildUserContext(persona);
console.log(`[BuildAgentContext WF3C] userId=${userId?.slice(0,8)}... | facts=${keyFacts.length} | memories=${relevantMemories.length} | goals=${goalsAndAspirations.length} | relationships=${relationshipFacts.length}`);

return {
  json: {
    ...payload,
    USER_CONTEXT: userContext,
    _context_built: true,
    _facts_count: keyFacts.length,
    _memories_count: relevantMemories.length
  }
};

const input = JSON.parse($input.first().json.query || '{}');
const query = input.query || input.q || '';
const limit = input.limit || 3;
const ctx    = $('Load Credentials').first().json;
const creds  = ctx.credentials || {};
const i18n   = ctx.i18n || {};
const userId = ctx.userId;
const dbUrl  = creds.database_url || $env.DATABASE_URL || '';
const persona = ctx._persona || ctx.persona || {};
const tokens  = persona.tokens || {};
const embedKey = tokens.openrouter_access_token || $env.OPENROUTER_API_KEY || '';

if (!dbUrl)   return { json: { error: `Database ${i18n.not_connected||'not connected'}`, memories: [] } };
if (!query || query.length < 3) return { json: { error: 'Query too short', memories: [] } };
if (!embedKey) return { json: { error: 'OpenRouter key not configured', memories: [] } };

try {
  const embedRes = await fetch('https://openrouter.ai/api/v1/embeddings', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${embedKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'openai/text-embedding-3-small', input: query })
  });
  if (!embedRes.ok) return { json: { error: `Embed failed: ${embedRes.status}`, memories: [] } };
  const embedData = await embedRes.json();
  const embedding = embedData.data?.[0]?.embedding;
  if (!embedding) return { json: { error: 'No embedding returned', memories: [] } };

  const { Pool } = require('pg');
  const pool = new Pool({ connectionString: dbUrl });
  const vectorStr = `[${embedding.join(',')}]`;
  const result = await pool.query(
    `SELECT content, metadata, created_at,
            1 - (embedding <=> $1::vector) AS similarity
     FROM user_data_schema.memory_embeddings
     WHERE user_id = $2 AND embedding IS NOT NULL
       AND 1 - (embedding <=> $1::vector) > 0.6
     ORDER BY embedding <=> $1::vector LIMIT $3`,
    [vectorStr, userId, limit]
  );
  await pool.end();
  const memories = result.rows.map(r => ({
    content: r.content,
    similarity: parseFloat(r.similarity.toFixed(3)),
    metadata: r.metadata || {},
    date: new Date(r.created_at).toLocaleDateString('th-TH')
  }));
  if (memories.length === 0) return { json: { message: 'No relevant memories found', memories: [], query } };
  return { json: { memories, count: memories.length, query } };
} catch(err) {
  return { json: { error: `${i18n.error||'Error'}: ${err.message}`, memories: [] } };
}

const input = JSON.parse($input.first().json.query || '{}');
const type   = (input.type || input.data_type || 'quote').toLowerCase();
const ctx    = $('Load Credentials').first().json;
const creds  = ctx.credentials || {};
const i18n   = ctx.i18n || {};
const apiKey = creds.finnhub_api_key || $env.FINNHUB_API_KEY || '';
const BASE   = 'https://finnhub.io/api/v1';

try {
  if (type === 'quote') {
    const symbol = (input.symbol || '').toUpperCase();
    if (!symbol) return { json: { error: i18n.symbol_required || 'symbol required' } };
    if (!apiKey) return { json: { error: `Finnhub API ${i18n.not_connected}`, help: i18n.configure } };
    const res  = await fetch(`${BASE}/quote?symbol=${symbol}&token=${apiKey}`);
    const data = await res.json();
    if (data.error) return { json: { error: data.error } };
    return { json: { symbol, currentPrice: data.c, change: data.d, changePercent: data.dp, high: data.h, low: data.l, open: data.o, prevClose: data.pc, timestamp: new Date().toISOString(), message: `${symbol}: $${data.c} (${data.dp > 0 ? '+' : ''}${data.dp?.toFixed(2)}%)` } };
  }
  if (type === 'news') {
    const symbol = (input.symbol || '').toUpperCase();
    if (!symbol) return { json: { error: i18n.symbol_required || 'symbol required' } };
    if (!apiKey) return { json: { error: `Finnhub API ${i18n.not_connected}`, help: i18n.configure } };
    const today = new Date().toISOString().split('T')[0];
    const week  = new Date(Date.now()-7*86400000).toISOString().split('T')[0];
    const res   = await fetch(`${BASE}/company-news?symbol=${symbol}&from=${week}&to=${today}&token=${apiKey}`);
    const news  = await res.json();
    const top5  = (news||[]).slice(0,5).map(n => ({ headline: n.headline, summary: n.summary?.slice(0,200), url: n.url, date: new Date(n.datetime*1000).toLocaleDateString() }));
    return { json: { symbol, news: top5, count: top5.length } };
  }
  if (type === 'profile') {
    const symbol = (input.symbol || '').toUpperCase();
    if (!symbol) return { json: { error: i18n.symbol_required || 'symbol required' } };
    if (!apiKey) return { json: { error: `Finnhub API ${i18n.not_connected}`, help: i18n.configure } };
    const res  = await fetch(`${BASE}/stock/profile2?symbol=${symbol}&token=${apiKey}`);
    const data = await res.json();
    return { json: { symbol, name: data.name, industry: data.finnhubIndustry, country: data.country, marketCap: data.marketCapitalization, logo: data.logo } };
  }
  if (type === 'crypto') {
    const coinId = input.coin_id || input.symbol || 'bitcoin';
    const res = await fetch(`https://api.coingecko.com/api/v3/simple/price?ids=${coinId}&vs_currencies=usd,thb&include_24hr_change=true&include_market_cap=true`);
    const data = await res.json();
    if (!data[coinId]) return { json: { error: `Coin '${coinId}' not found. Try: bitcoin, ethereum, solana` } };
    return { json: { coin: coinId, ...data[coinId], timestamp: new Date().toISOString() } };
  }
  if (type === 'fx_rates') {
    const base = (input.base || 'USD').toUpperCase();
    const res  = await fetch(`https://api.fxratesapi.com/latest?base=${base}&currencies=THB,EUR,JPY,GBP,SGD,CNY,KRW`);
    const data = await res.json();
    return { json: { base, rates: data.rates, date: data.date } };
  }
  return { json: { error: `Unknown type: ${type}. Use: quote, news, profile, crypto, fx_rates` } };
} catch(e) {
  return { json: { error: `${i18n.error||'Error'}: ${e.message}` } };
}

const input  = JSON.parse($input.first().json.query || '{}');
const from   = (input.from || 'USD').toUpperCase();
const to     = (input.to || 'THB').toUpperCase();
const amount = parseFloat(input.amount || 1);
const i18n   = $('Load Credentials').first().json.i18n || {};
try {
  const res  = await fetch(`https://api.exchangerate-api.com/v4/latest/${from}`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const data = await res.json();
  const rate = data.rates[to];
  if (!rate) return { json: { error: `Currency ${to} not found` } };
  const converted = (amount * rate).toFixed(2);
  return { json: { from, to, amount, rate: rate.toFixed(6), converted: parseFloat(converted), message: `${amount} ${from} = ${converted} ${to} (rate: ${rate.toFixed(4)})`, date: data.date } };
} catch(err) {
  return { json: { error: `${i18n.error||'Error'}: ${err.message}` } };
}

const input  = JSON.parse($input.first().json.query || '{}');
const action = (input.action || 'add').toLowerCase();
const ctx    = $('Load Credentials').first().json;
const creds  = ctx.credentials || {};
const i18n   = ctx.i18n || {};
const userId = ctx.userId;
const dbUrl  = creds.database_url || $env.DATABASE_URL || '';
if (!dbUrl) return { json: { error: i18n.not_connected || 'Database not connected' } };
const { Pool } = require('pg');
const pool = new Pool({ connectionString: dbUrl });
try {
  if (action === 'add') {
    const type     = (input.type || 'expense').toLowerCase();
    const amount   = parseFloat(input.amount || 0);
    const category = input.category || 'general';
    const note     = input.note || '';
    const currency = input.currency || 'THB';
    if (amount <= 0) return { json: { error: i18n.amount_required || 'Valid amount required' } };
    await pool.query(`INSERT INTO user_data_schema.budget_entries (user_id, type, amount, category, note, currency, created_at) VALUES ($1, $2, $3, $4, $5, $6, NOW())`, [userId, type, amount, category, note, currency]);
    await pool.end();
    return { json: { success: true, type, amount, category, currency, message: `${type === 'income' ? '💰' : '💸'} ${type} ${amount} ${currency} recorded` } };
  } else if (action === 'summary') {
    const months = input.months || 1;
    const result = await pool.query(`SELECT type, SUM(amount) as total, currency FROM user_data_schema.budget_entries WHERE user_id = $1 AND created_at >= NOW() - INTERVAL '${months} months' GROUP BY type, currency`, [userId]);
    await pool.end();
    const income  = result.rows.filter(r => r.type === 'income').reduce((s,r) => s + parseFloat(r.total), 0);
    const expense = result.rows.filter(r => r.type === 'expense').reduce((s,r) => s + parseFloat(r.total), 0);
    return { json: { income, expense, balance: income - expense, rows: result.rows, period: `${months} month(s)` } };
  } else if (action === 'categories') {
    const result = await pool.query(`SELECT category, SUM(amount) as total, COUNT(*) as count FROM user_data_schema.budget_entries WHERE user_id = $1 AND type = 'expense' AND created_at >= NOW() - INTERVAL '1 month' GROUP BY category ORDER BY total DESC`, [userId]);
    await pool.end();
    return { json: { categories: result.rows } };
  }
  await pool.end();
  return { json: { error: 'Unknown action. Use: add | summary | categories' } };
} catch(err) {
  try { await pool.end(); } catch(e) {}
  return { json: { error: `${i18n.error||'Error'}: ${err.message}` } };
}

const input = JSON.parse($input.first().json.query || '{}');
const ctx  = $('Load Credentials').first().json;
const i18n = ctx.i18n || {};
const lang = ctx.lang || 'th';
const type = (input.calc_type || 'thai_income_tax').toLowerCase();
const disclaimers = { th: '⚠️ ประมาณการเบื้องต้น กรุณาปรึกษานักบัญชีหรือสรรพากร', en: '⚠️ Preliminary estimate only. Please consult an accountant or tax authority.', ja: '⚠️ 概算のみです。会計士または税務機関にご相談ください。', zh: '⚠️ 仅为初步估算。请咨询会计师或税务机关。' };
const disclaimer = disclaimers[lang] || disclaimers['en'];
try {
  if (type === 'thai_income_tax') {
    const income = parseFloat(input.annual_income || 0);
    const extraDeduct = parseFloat(input.deductions || 0);
    const personalDeduct = 60000;
    const ssoDeduct = Math.min(income * 0.05, 9000);
    const totalDeduct = personalDeduct + ssoDeduct + extraDeduct;
    const taxable = Math.max(0, income - totalDeduct);
    const brackets = [[0,150000,0],[150001,300000,0.05],[300001,500000,0.10],[500001,750000,0.15],[750001,1000000,0.20],[1000001,2000000,0.25],[2000001,5000000,0.30],[5000001,Infinity,0.35]];
    let tax = 0;
    for (const [min, max, rate] of brackets) { if (taxable <= min) break; tax += (Math.min(taxable, max) - min) * rate; }
    return { json: { calc_type: type, annual_income: income, total_deductions: totalDeduct, taxable_income: taxable, estimated_tax: Math.round(tax), effective_rate_pct: income > 0 ? Math.round(tax/income*1000)/10 : 0, monthly_withholding: Math.round(tax/12), disclaimer } };
  }
  if (type === 'compound_interest') {
    const p = parseFloat(input.principal || 0); const r = parseFloat(input.rate_pct || 0) / 100; const n = parseInt(input.years || 1);
    const final = p * Math.pow(1 + r, n);
    return { json: { calc_type: type, principal: p, rate_pct: r*100, years: n, final_amount: Math.round(final), gain: Math.round(final - p), gain_pct: Math.round((final/p - 1)*1000)/10, disclaimer } };
  }
  if (type === 'loan_payment') {
    const p = parseFloat(input.principal || 0); const r = parseFloat(input.annual_rate_pct || 0) / 100 / 12; const n = parseInt(input.years || 1) * 12;
    const pmt = r === 0 ? p/n : p * (r * Math.pow(1+r,n)) / (Math.pow(1+r,n) - 1);
    return { json: { calc_type: type, principal: p, monthly_payment: Math.round(pmt), total_paid: Math.round(pmt*n), total_interest: Math.round(pmt*n - p), disclaimer } };
  }
  if (type === 'savings_goal') {
    const goal = parseFloat(input.goal || 0); const initial = parseFloat(input.initial || 0); const monthly = parseFloat(input.monthly_savings || 0); const r = parseFloat(input.rate_pct || 0) / 100 / 12;
    let balance = initial, months = 0;
    while (balance < goal && months < 1200) { balance = balance * (1 + r) + monthly; months++; }
    return { json: { calc_type: type, goal, initial, monthly_savings: monthly, months_to_goal: months, years_to_goal: Math.round(months/12*10)/10, achievable: months < 1200, disclaimer } };
  }
  return { json: { error: `Unknown calc_type: ${type}` } };
} catch(e) { return { json: { error: e.message } }; }
